// ✅ SENIOR PATTERN: Renting and returning buffers from ArrayPool
public async Task ProcessUploadAsync(Stream stream) {
    byte[] buffer = ArrayPool<byte>.Shared.Rent(128 * 1024);
    try {
        int bytesRead = await stream.ReadAsync(buffer.AsMemory(0, 128 * 1024));
        // process bytesRead...
    } finally {
        ArrayPool<byte>.Shared.Return(buffer, clearArray: false);
    }
}

