// ❌ BAD: Anemic entity with public setters and null-forgiving silence
public class MoneyAccount {
    public decimal Balance { get; set; }
    public string Currency { get; set; } = null!;
}
// Runtime bug: Balance can become negative or Currency empty undetected!

solutionSnippet:
// ✅ SENIOR PATTERN: Invariant validation in strongly-typed factory/constructor
public sealed class MoneyAccount {
    public decimal Balance { get; private set; }
    public CurrencyCode Currency { get; }

    private MoneyAccount(decimal initialBalance, CurrencyCode currency) {
        ArgumentOutOfRangeException.ThrowIfNegative(initialBalance);
        Balance = initialBalance;
        Currency = currency ?? throw new ArgumentNullException(nameof(currency));
    }
}

